do $seed$ declare t_id uuid; begin
  select id into t_id from public.tools where nombre = $q$SMTP$q$ order by created_at limit 1;
  if t_id is null then
  else
    update public.tools set protocolo = $q$SMTP (25/465/587 tcp)$q$, descripcion = $q$Simple Mail Transfer Protocol. Protocolo para envio de correo entre servidores. En enumeracion buscamos el banner del servidor, los comandos soportados (con EHLO) y sobre todo enumerar usuarios validos abusando de VRFY, EXPN y RCPT TO. Herramientas clave: nmap, telnet/nc y smtp-user-enum.$q$ where id = t_id;
    delete from public.commands where tool_id = t_id;
    delete from public.exercises where tool_id = t_id;
  end if;
end $seed$;

do $seed$ declare t_id uuid; begin
  select id into t_id from public.tools where nombre = $q$IMAP/POP3$q$ order by created_at limit 1;
  if t_id is null then
  else
    update public.tools set protocolo = $q$IMAP (143/993 tcp) POP3 (110/995 tcp)$q$, descripcion = $q$Protocolos de lectura de correo. POP3 descarga los mensajes al cliente, IMAP los mantiene sincronizados en el servidor. En enumeracion buscamos el banner, mecanismos de autenticacion soportados, si hay TLS y probamos credenciales validas. Herramientas clave: nmap, openssl s_client y curl.$q$ where id = t_id;
    delete from public.commands where tool_id = t_id;
    delete from public.exercises where tool_id = t_id;
  end if;
end $seed$;

do $seed$ declare t_id uuid; begin
  select id into t_id from public.tools where nombre = $q$Oracle TNS$q$ order by created_at limit 1;
  if t_id is null then
  else
    update public.tools set protocolo = $q$Oracle TNS (1521 tcp)$q$, descripcion = $q$Transparent Network Substrate. Es el listener de Oracle Database, la puerta por donde los clientes piden conexion a las instancias. En enumeracion buscamos la version del listener, los SIDs disponibles y credenciales validas para conectarnos al servicio. Herramientas clave: nmap, odat (Oracle Database Attacking Tool) y sqlplus.$q$ where id = t_id;
    delete from public.commands where tool_id = t_id;
    delete from public.exercises where tool_id = t_id;
  end if;
end $seed$;

do $seed$ declare t_id uuid; begin
  select id into t_id from public.tools where nombre = $q$IPMI$q$ order by created_at limit 1;
  if t_id is null then
  else
    update public.tools set protocolo = $q$IPMI (623 udp)$q$, descripcion = $q$Intelligent Platform Management Interface. Protocolo de gestion fuera de banda que usan las BMC (iDRAC, iLO, IMM) para administrar servidores fisicos. La version 2.0 tiene fallos conocidos como el volcado de hashes de autenticacion (cipher zero y RAKP), lo que la vuelve un objetivo jugoso. Herramientas clave: nmap, metasploit e ipmitool.$q$ where id = t_id;
    delete from public.commands where tool_id = t_id;
    delete from public.exercises where tool_id = t_id;
  end if;
end $seed$;